import { useEffect } from 'react';

function MyComponent() {
  // Runs after every render
  useEffect(() => {
    console.log('Rendered!');
  });

  // Runs only once (on mount)
  useEffect(() => {
    console.log('Mounted!');
  }, []);

  // Runs when value changes
  useEffect(() => {
    console.log('Value changed:', value);
  }, [value]);
}

function Page({ title }) {
  useEffect(() => {
    document.title = title;
  }, [title]);

  return <h1>{title}</h1>;
}
